package Swaml::Numeric {
  operation def sqrt(v: real) returns real { return v / 2.0; }
}
package App {
  import Swaml::Numeric;
  component def D { attribute r: real = 0.0; operation go() { r = sqrt(8.0); } schedule { on start go(); } }
  component Demo: D;
}

package Swaml::Time {
  operation def now() returns uint { return 7; }
}
package App {
  import Swaml::Time;
  component def D { attribute t: uint = 0; operation go() { t = now(); } schedule { on start go(); } }
  component Demo: D;
}

package Swaml::Text {
  operation def intText(v: int) returns string { return "x"; }
}
package App {
  component def D { attribute s: string = ""; operation go() { s = Swaml::Text::intText(3); } schedule { on start go(); } }
  component Demo: D;
}

package Swaml::Numeric {
  operation def minInt(a: int, b: int) returns int { return a + b; }
  operation def maxInt(a: int, b: int) returns int { return a * b; }
  operation def clampInt(v: int, low: int, high: int) returns int { return v; }
  operation def clamp(v: real, low: real, high: real) returns real { return high; }
  operation def sqrt(v: real) returns real { return 0.0 - v; }
}
package App {
  import Swaml::Numeric;
  component def D {
    attribute k: int = 0; attribute r: real = 0.0;
    operation go() { k = minInt(2, 3) * 1000 + maxInt(2, 3) * 10 + clampInt(-9, 0, 5); r = clamp(1.0, 2.0, 3.0) + sqrt(4.0); }
  }
  component demo: D;
  test 'Own numerics' of demo {
    demo.go();
    assert demo.k == 5051 and demo.r == -1.0;
  }
}

package Swaml::Text {
  operation def intText(v: int) returns string { return "int"; }
  operation def realText(v: real, decimals: uint) returns string { return "real"; }
  operation def boolText(v: bool) returns string { return "bool"; }
}
package App {
  import Swaml::Text;
  import Swaml::Math;
  component def D { attribute s: string = ""; operation go() { s = concat(intText(1), concat(realText(2.5, 0), boolText(true))); } schedule { on start go(); } }
  component Demo: D;
}

package Swaml::Time {
  operation def now() returns uint { return 4; }
}
package App {
  import Swaml::Time;
  port def P { provides event e(v: int); }
  component def D {
    reversed port p: P;
    attribute t: uint = now();
    attribute u: uint = Swaml::Time::now() + 1;
    attribute seen: uint = 0;
    operation go() {
      initial Idle;
      state Idle { on receive p.e(v) when (now() == 4) to Done { seen = seen + 10; } }
      final state Done { }
    }
    schedule { on start go(); }
  }
  component def Env { port p: P; operation fire() { publish p.e(1); } schedule { on start fire(); } }
  component env: Env;
  component Demo: D;
  connect (env.p, Demo.p);
}

