package Swaml::Numeric { operation def sqrt(v: real) returns real { return v; } }
package Swaml::Numeric { }
package App { import Swaml::Numeric; component def D { attribute r: real = 0.0; operation go() { r = sqrt(1.0); } } component Demo: D; }

package Swaml::Numeric { operation def sqrt(v: real) returns real { return v; } }
package Other { operation def sqrt(v: real) returns real { return v + 1.0; } }
package App {
  import Swaml::Numeric;
  import Other;
  component def D { attribute r: real = 0.0; operation go() { r = sqrt(4.0); } }
  component Demo: D;
}

package Swaml::Time {
  datatype Stamp { ns: uint; }
  enum Unit { ns, us }
  component def Clock { attribute stamp: Stamp = record Stamp { ns = 3; }; operation now() returns uint { return stamp.ns; } }
}
package App {
  import Swaml::Time;
  component def D { component clock: Clock; attribute u: Unit = Unit.us; attribute last: Stamp = record Stamp { ns = 0; }; }
  component Demo: D;
}

package Swaml::Numeric { operation def sqrt(v: real) returns real { return v * 3.0; } }
package App {
  component def D { attribute r: real = 0.0; operation root: Swaml::Numeric::sqrt; operation go() { r = root(2.0); } schedule { on start go(); } }
  component Demo: D;
}

package Swaml::Time { operation def now() returns uint { return 1; } }
package App {
  import Swaml::Time;
  component def D {
    attribute clock: uint = 0; attribute last: uint = 0;
    operation tick() { clock = clock + 1; }
    operation go() { var t: uint = clock + now(); wait 1ms; last = t; }
    schedule { on start go(); on every 500us tick(); }
  }
  component Demo: D;
}
